def validate_raw(topics, name):
    print(f"Validating {len(topics)} {name} topics...")
    assert len(topics) == 100, f"Expected 100 topics for {name}, got {len(topics)}"
    for idx, t in enumerate(topics):
        title, subj, sys_name, hallmark, ref_l, ref_u = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject {subj} in {name} #{idx+1}: {title}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system {sys_name} in {name} #{idx+1}: {title}"
        assert len(title) >= 10, f"Title too short in {name} #{idx+1}"
        assert len(hallmark) >= 20, f"Hallmark too short in {name} #{idx+1}"
        assert len(ref_l) >= 5, f"Ref label too short in {name} #{idx+1}"
        assert ref_u.startswith("https://"), f"Ref url invalid in {name} #{idx+1}"
    print(f"Validated 100 {name} topics successfully.")

def write_topics_file():
    out_path = os.path.join(os.path.dirname(__file__), "mega59_topics_b.py")
    with open(out_path, "w", encoding="utf-8") as f:
        f.write('"""Mega-Batch 59 Topics Part B: PLAB / UKMLA (100), AMC (100), MCCQE (100)"""\n\n')
        f.write(f"PLAB_TOPICS = {repr(PLAB_RAW)}\n\n")
        f.write(f"AMC_TOPICS = {repr(AMC_RAW)}\n\n")
        f.write(f"MCCQE_TOPICS = {repr(MCCQE_RAW)}\n")
    print(f"Wrote {out_path} successfully.")

if __name__ == "__main__":
    validate_raw(PLAB_RAW, "PLAB / UKMLA")
    validate_raw(AMC_RAW, "AMC")
    validate_raw(MCCQE_RAW, "MCCQE")
    write_topics_file()
